-- Public identity is separate from immutable accounts.id. Existing numeric IDs remain reserved.
ALTER TABLE accounts ADD COLUMN auth_mode TEXT NOT NULL DEFAULT 'pin';
ALTER TABLE user_ids ADD COLUMN reserved_until INTEGER NOT NULL DEFAULT 0;
CREATE TABLE account_emails(account_id TEXT PRIMARY KEY REFERENCES accounts(id),email_norm TEXT NOT NULL UNIQUE,verified_at INTEGER NOT NULL);
CREATE TABLE account_access_state(account_id TEXT PRIMARY KEY REFERENCES accounts(id),funds_activated_at INTEGER NOT NULL DEFAULT 0,ever_strong INTEGER NOT NULL DEFAULT 0,credential_version INTEGER NOT NULL DEFAULT 1,protected_until INTEGER NOT NULL DEFAULT 0,risk_review_required INTEGER NOT NULL DEFAULT 0,recovery_confirmed_at INTEGER NOT NULL DEFAULT 0,id_changed_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE account_passkeys(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),public_key BLOB NOT NULL,counter INTEGER NOT NULL,transports TEXT NOT NULL,device_type TEXT NOT NULL,backed_up INTEGER NOT NULL,name TEXT NOT NULL,created_at INTEGER NOT NULL,last_used_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX account_passkeys_owner ON account_passkeys(account_id);
CREATE TABLE account_access_challenges(id TEXT PRIMARY KEY,kind TEXT NOT NULL,account_id TEXT REFERENCES accounts(id),email_norm TEXT NOT NULL DEFAULT '',session_hash TEXT NOT NULL DEFAULT '',device_hash TEXT NOT NULL DEFAULT '',purpose TEXT NOT NULL DEFAULT '',challenge TEXT NOT NULL DEFAULT '',code_hash TEXT NOT NULL DEFAULT '',request_id TEXT UNIQUE,input_digest TEXT NOT NULL DEFAULT '',credential_version INTEGER NOT NULL DEFAULT 0,recovery_grant_hash TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX account_access_email_challenges ON account_access_challenges(email_norm,kind,created_at);
CREATE TABLE account_strong_proofs(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),session_hash TEXT NOT NULL,purpose TEXT NOT NULL,credential_id TEXT NOT NULL REFERENCES account_passkeys(id) ON DELETE CASCADE,credential_version INTEGER NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE account_recovery_grants(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),credential_version INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE account_access_audit(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),event TEXT NOT NULL,created_at INTEGER NOT NULL,detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE account_security_notifications(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),recipient_email TEXT NOT NULL,event TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
